{'content': '// Towel Hook for M3 Flat Head Screw
// Designed for 3D printing and strength
$fn = 64;

// Parameters
width = 18;
base_h = 50;
base_t = 6;
extension = 35;
hook_up = 20;
thickness = 10;

// Screw parameters (M3 flat head)
screw_d = 3.6;
head_d = 6.5;
head_depth = 3.5;

module towel_hook() {
    difference() {
        union() {
            // Vertical base plate
            cube([width, base_t, base_h]);

            // Horizontal arm (slanted slightly up for gravity)
            translate([0, base_t, 0])
            rotate([-5, 0, 0])
            cube([width, extension, thickness]);

            // Hook tip
            translate([0, base_t + extension - thickness, 0])
            cube([width, thickness, hook_up + thickness]);

            // Reinforcing gusset (triangle)
            translate([0, base_t, thickness])
            polyhedron(
                points=[
                    [0, 0, 0], [width, 0, 0], [width, extension*0.7, 0], [0, extension*0.7, 0],
                    [0, 0, base_h - thickness - 5], [width, 0, base_h - thickness - 5]
                ],
                faces=[
                    [0,1,2,3], // bottom
                    [4,5,1,0], // back
                    [3,2,5,4], // slope
                    [0,3,4], [1,5,2] // sides
                ]
            );
        }

        // Screw Hole for M3 Flat Head (Centered and high)
        translate([width/2, base_t + 0.1, base_h - 10])
        rotate([90, 0, 0]) {
            // Shank
            cylinder(d = screw_d, h = base_t + 0.2);
            // Countersink
            translate([0, 0, base_t - head_depth + 0.2])
            cylinder(d1 = screw_d, d2 = head_d, h = head_depth + 0.1);
        }

        // Round off the front top of the hook tip
        translate([-1, base_t + extension, hook_up + thickness])
        rotate([45, 0, 0])
        cube([width + 2, 10, 10]);
    }
}

towel_hook();
'}

{'content': '// Towel Hook for M3 Flat Head Screw
// Designed for 3D printing (print on side for maximum strength)
$fn = 64;

// Parameters
width = 16;
base_h = 60;
base_t = 8;
arm_len = 35;
tip_h = 15;
thickness = 10;

// Screw parameters (M3 flat head)
screw_d = 3.6;
head_d = 7.0;
head_depth = 4.0;

module profile() {
    polygon(points=[
        [0, 0],
        [base_t + arm_len, 0],
        [base_t + arm_len, thickness + tip_h],
        [base_t + arm_len - thickness, thickness + tip_h],
        [base_t + arm_len - thickness, thickness],
        [base_t, thickness],
        [base_t, base_h],
        [0, base_h]
    ]);
}

module towel_hook() {
    difference() {
        // Extrude the hook profile
        rotate([90, 0, 90])
        linear_extrude(height = width)
        profile();

        // Top Screw Hole for M3 Flat Head
        translate([width/2, -0.1, base_h - 12])
        rotate([-90, 0, 0]) {
            cylinder(d = screw_d, h = base_t + 0.2);
            cylinder(d1 = head_d, d2 = screw_d, h = head_depth);
        }

        // Let's add a second hole for stability? The prompt said "a single M3 screw".
        // I will stick to one as requested, but place it optimally.

        // Soften the corners of the base
        translate([-1, 0, 0]) rotate([0, 90, 0]) cylinder(r=2, h=width+2);
        translate([-1, 0, base_h]) rotate([0, 90, 0]) cylinder(r=2, h=width+2);
    }

    // Add a small fillet/support in the corner
    translate([0, base_t, thickness])
    rotate([0, 90, 0])
    linear_extrude(height = width)
    polygon(points=[[0,0], [15,0], [0,15]]);
}

towel_hook();
'}

