// Designed for 3D printing (print on its side for best strength)
$fn = 64;

// Global dimensions
W = 18;      // Width of the hook
H = 65;      // Total height
D = 45;      // Total depth
T = 10;      // Thickness of the arm/hook
BT = 8;      // Base plate thickness

// Screw dimensions (M3 Flat Head)
SCREW_D = 3.6;
HEAD_D = 6.8;
HEAD_H = 3.0;

module hook_shape() {
    difference() {
        union() {
            // Main vertical base
            cube([W, BT, H]);

            // Horizontal arm (with slight upward angle for retention)
            translate([0, BT, 0])
            rotate([-5, 0, 0])
            cube([W, D-BT, T]);

            // Hook tip
            translate([0, D-T, 0])
            cube([W, T, T + 20]);

            // Reinforcing gusset (triangle) to handle large towel weight
            translate([0, BT, T-0.1])
            linear_extrude(height = H - T - 15)
            polygon(points=[[0,0], [W,0], [W/2, D*0.4]]);
            // Note: the above polygon was a bit wrong in orientation. Let's fix.
        }
    }
}

// Improved version with cleaner construction
module towel_hook_v2() {
    difference() {
        union() {
            // 1. Vertical Base plate
            cube([W, BT, H]);

            // 2. The Hook Arm and Tip (Modeled as a single path)
            translate([0, BT, 0])
            rotate([90, 0, 90])
            linear_extrude(height = W)
            polygon(points=[
                [0,0], 
                [D-BT, 0], 
                [D-BT, T+15], 
                [D-BT-T, T+15], 
                [D-BT-T, T], 
                [0, T]
            ]);

            // 3. Structural Gusset (Large triangle for support)
            translate([0, BT, T-1])
            rotate([90, 0, 90])
            linear_extrude(height = W)
            polygon(points=[
                [0,0],
                [D-BT-T-5, 0],
                [0, H-T-15]
            ]);
        }

        // Screw Hole for M3 Flat Head
        // Placed high to resist the pulling torque of a heavy towel
        translate([W/2, -0.1, H - 12])
        rotate([-90, 0, 0]) {
            // Drill hole
            cylinder(d = SCREW_D, h = BT + 0.2);
            // Countersink
            cylinder(d1 = HEAD_D, d2 = SCREW_D, h = HEAD_H + 0.1);
        }

        // Round off the very top of the hook tip for safety
        translate([-1, D, T+15])
        rotate([45, 0, 0])
        cube([W+2, 10, 10]);

        // Round off the top of the wall plate
        translate([-1, 0, H])
        rotate([0, 90, 0])
        cylinder(r=2, h=W+2);
    }
}

towel_hook_v2();
"}

{'content': '// Towel Hook for M3 Flat Head Screw
// Designed for 3D printing (Recommended: print on side for max strength)
$fn = 64;

// Global dimensions
W = 18;      // Width of the hook
H = 65;      // Total height
D = 45;      // Total depth
T = 10;      // Thickness of the arm/hook
BT = 8;      // Base plate thickness

// Screw dimensions (M3 Flat Head)
SCREW_D = 3.6;
HEAD_D = 6.8;
HEAD_H = 3.2;

module towel_hook_v3() {
    difference() {
        union() {
            // Main structure extruded from the side profile
            // This ensures a clean look and easy fillets
            rotate([90, 0, 90])
            linear_extrude(height = W)
            polygon(points=[
                [0, 0],             // Bottom back
                [D, 0],             // Bottom front
                [D, T + 18],        // Tip top
                [D - T, T + 18],    // Tip inner top
                [D - T, T],         // Arm top
                [BT, T],            // Above gusset
                [BT, H],            // Back top front
                [0, H]              // Back top back
            ]);

            // Large structural gusset for heavy towels
            rotate([90, 0, 90])
            linear_extrude(height = W)
            polygon(points=[
                [BT, T],
                [D - T - 5, T],
                [BT, H - 15]
            ]);
        }

        // M3 Flat Head Screw Hole
        // Positioned high to handle the leverage of a heavy towel
        translate([W/2, -0.1, H - 10])
        rotate([-90, 0, 0]) {
            // Shaft
            cylinder(d = SCREW_D, h = BT + 0.2);
            // Countersink (y increases into the part)
            // d1 is at y=0, d2 is at y=HEAD_H
            cylinder(d1 = HEAD_D, d2 = SCREW_D, h = HEAD_H);
        }

        // Aesthetic / Safety Rounding
        // Round the very front of the hook
        translate([-1, D, T+18]) rotate([45, 0, 0]) cube([W+2, 10, 10]);
        // Round the back top
        translate([-1, 0, H]) rotate([0, 90, 0]) cylinder(r=2, h=W+2);
    }
}

towel_hook_v3();
'}
